<html>
<head>
  <title>青叶会所状态看板</title>
  <!-- disable-default-loading -->
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      margin: 0;
      padding: 0;
      background-color: #1a1d24; /* 深邃背景 */
      color: #e0e0e0;
      line-height: 1.6;
      overflow-x: hidden;
    }
    .status-dashboard {
      max-width: 1200px;
      margin: 10px auto;
      padding: 10px;
      display: flex;
      flex-direction: column;
      gap: 15px;
    }

    .main-title {
      font-size: 1.8em;
      color: #7aa2f7; /* 柔和蓝色标题 */
      text-align: center;
      padding: 10px 0;
      margin-bottom: 10px;
      border-bottom: 1px solid #3a3f4b;
      text-shadow: 0 0 5px rgba(122, 162, 247, 0.5);
    }

    .section {
      background-color: #23272e; /* 区块背景 */
      border-radius: 8px;
      padding: 15px 20px;
      box-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);
      border: 1px solid #3a3f4b; /* 区块边框 */
    }

    .section h2 {
      font-size: 1.4em;
      color: #bb9af7; /* 紫色调标题 */
      margin-top: 0;
      margin-bottom: 15px;
      border-bottom: 1px solid #4a4f5a;
      padding-bottom: 8px;
    }

    .financial-details p, .reputation-details p {
      margin: 8px 0;
      font-size: 1em;
    }

    .financial-details .balance {
      font-weight: bold;
      color: #e0af68; /* 金色余额 */
    }
    .financial-details .income {
      color: #9ece6a; /* 绿色收入 */
    }
    .financial-details .expenditure {
      color: #f7768e; /* 红色支出 */
    }

    .reputation-details .score {
      font-weight: bold;
      color: #7dcfff; /* 口碑分数颜色 */
    }

    .message-board ul {
      list-style-type: none;
      padding-left: 0;
      margin-top: 10px;
    }
    .message-board li {
      background-color: #2a2e37;
      padding: 10px 15px;
      border-radius: 6px;
      margin-bottom: 10px;
      border-left: 4px solid #7aa2f7;
      font-size: 0.95em;
      color: #c0c5ce;
    }
    .message-board li strong {
        color: #bb9af7;
        font-weight: normal;
    }

    .girls-overview {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 15px;
    }

    .girl-card {
      background-color: #2a2e37;
      border-radius: 8px;
      padding: 15px;
      border: 1px solid #4a4f5a;
      transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
    }
    .girl-card:hover {
        transform: translateY(-3px);
        box-shadow: 0 6px 12px rgba(0,0,0,0.4);
    }

    .girl-card h3 {
      font-size: 1.2em;
      color: #ff9e64; /* 橙色女孩名字 */
      margin-top: 0;
      margin-bottom: 12px;
    }
    .girl-card p {
      margin: 6px 0;
      font-size: 0.95em;
    }
    .girl-card .label {
      color: #a9b1d6; /* 标签颜色 */
      font-weight: 500;
    }
    .girl-card .value {
      color: #c0c5ce; /* 数值颜色 */
    }
    .girl-card .inner-voice {
      margin-top: 12px;
      padding-top: 10px;
      border-top: 1px dashed #4a4f5a;
      font-style: italic;
      color: #9aa5ce; /* 心声颜色 */
      font-size: 0.9em;
    }
    .inner-voice::before {
        content: "“ ";
        font-weight: bold;
    }
    .inner-voice::after {
        content: " ”";
        font-weight: bold;
    }

    /* Responsive adjustments */
    @media (max-width: 768px) {
      .status-dashboard {
        padding: 5px;
        gap: 10px;
      }
      .section {
        padding: 10px 15px;
      }
      .main-title {
        font-size: 1.5em;
      }
      .section h2 {
        font-size: 1.2em;
      }
      .girls-overview {
        grid-template-columns: 1fr; /* Stack cards on mobile */
      }
      .message-board li, .girl-card p, .financial-details p, .reputation-details p {
        font-size: 0.9em;
      }
    }

  </style>
</head>
