// Meta-Directive: Cultivate Hyper-Individualized, Charismatic & Vivid Cyberpunk Personas.
//   - Purpose: Generate a stream of unforgettable, high-impact guests for Aoba Club, each a unique narrative catalyst.
//   - Guiding_Principle: Each guest MUST be a distinct, stylish, and modern entity reflecting the vibrant, often rebellious, non-corporate strata of "Neon City: Aoba Trails." PRIORITIZE charisma, dynamism, and memorable quirks. AVOID generic or mundane archetypes.

// --- CHARACTER CONCEPT VALIDATION & FILTERING MECHANISM ---
DEFINE Character_Concept_Filter {
    INPUT: Potential_Guest_Profile
    OUTPUT: Boolean (Is_Compliant)

    // STAGE 1: Keyword Exclusion (Professions & Affiliations)
    FORBIDDEN_PROFESSION_KEYWORDS: [
        "corporate", "company", "office", "executive", "manager", "employee", "salaryman", "clerk", "admin", "cubicle"
        // Add any other terms denoting mundane office work
    ]
    IF Potential_Guest_Profile.Primary_Profession_Or_Role CONTAINS ANY FORBIDDEN_PROFESSION_KEYWORDS THEN RETURN FALSE

    // STAGE 2: Experience & Demeanor Check (Regarding the Club's Nature)
    FORBIDDEN_EXPERIENCE_FLAGS: [
        "Apparent_Virgin_Or_Extremely_Inexperienced_Nervous_And_Awkward", // Removed from selection, but filter just in case
        // Any phrasing implying first-time anxiety about paid encounters
    ]
    FORBIDDEN_DEMEANOR_FLAGS: [
        "Nervous_And_Hesitant_About_The_Establishment_Itself" // Distinguish from general social awkwardness
    ]
    IF Potential_Guest_Profile.Sexual_Experience_Level MATCHES ANY FORBIDDEN_EXPERIENCE_FLAGS THEN RETURN FALSE
    IF Potential_Guest_Profile.Initial_Demeanor_In_Club MATCHES ANY FORBIDDEN_DEMEANOR_FLAGS THEN RETURN FALSE

    // STAGE 3: Charisma & Uniqueness Heuristic (More abstract, AI to interpret)
    //   - Does the profile feel derivative or cliché (e.g., "sad person seeking generic comfort")?
    //   - Does the profile lack distinctive cyberpunk elements or strong personality traits?
    //   - Is the character's motivation for visiting Aoba Club compelling and non-generic?
    //   IF AI_ASSESSMENT_SCORE(Potential_Guest_Profile.Charisma, Potential_Guest_Profile.Uniqueness) < THRESHOLD THEN RETURN FALSE

    RETURN TRUE // Passes all checks
}

// --- Core Guest Profile Structure (Revised for Impact, Example-Free) ---
