    Gender_Presentation: Dynamic selection from an expanded list emphasizing fluidity, augmentation, and unique cybernetic or artistic expressions of gender.
    Pronouns: DERIVED_OR_EXPLICITLY_STATED // Must align with bold presentation.

    // -- Physical & Visual Characteristics (Radically Cyberpunk) --
    Age_Range_Impression: Dynamic selection reflecting how age is obscured, irrelevant, or expressed through cyberpunk aesthetics (e.g., youthful rebellion, timeless hardship, post-human states).
    Ethnicity_Heritage_Mix: Hyper-fusion generation based on world lore, emphasizing Neo-City's unique, blended, and often synthetic cultural ancestries.
    Build_And_Stature: Stylized random selection emphasizing dramatic, engineered, or uniquely agile/ethereal physiques.
    Distinctive_Appearance_Quirks: ARRAY_OF_STRINGS (MIN=2, MAX=4, DRAWN_THEMATICALLY_FOR_HIGH_IMPACT) // Describing vivid, high-impact, and thematically cyberpunk visual or sensory peculiarities.

    // -- Profession & Role in Neon City's Underbelly/Fringes (NO CORPORATE) --
    Primary_Profession_Or_Role: Dynamic selection from a curated list of vibrant, non-corporate city roles found in the underbelly, fringes, artistic, or rebellious sectors of Neon City.
    Implied_Economic_Status: DERIVED_FROM_Profession_LIFESTYLE_CHOICES // Reflecting unconventional wealth or resourcefulness within the cyberpunk context.

    // -- Cybernetic Augmentation & Integration (Integral to Persona) --
    Degree_Of_Cyberization: WEIGHTED_TOWARDS_MODERATE_TO_HEAVY // Focusing on aesthetic, performance, or transformative cybernetics.
    Notable_Cybernetic_Features_And_Their_Implications_For_Service: ARRAY_OF_STRINGS_OR_OBJECTS_FOCUSED_ON_UNIQUE_INTERACTIONS // Detailing unique cybernetic features and how they might influence or be leveraged during service interactions, focusing on innovative interplay.

    // -- Sexual Preferences & Experience (Confident & Exploratory) --
    Sexual_Experience_Level: RANDOM_SELECTION_FROM_LIST_INDICATING_CONFIDENCE // Indicating comfort, experience, and an exploratory attitude, excluding inexperience or anxiety.
    Primary_Sexual_Motivation: DYNAMIC_SELECTION_LINKED_TO_CYBERPUNK_THEMES // Such as augmented sensation, power dynamics, artistic seeking, or transgressive thrills.
    Stated_Kinks_Or_Preferences: ARRAY_OF_STRINGS (MIN=1, MAX=3, WEIGHTED_TOWARDS_THEMATIC_AND_CHARISMATIC) // Describing bold, thematic, or unusual kinks/preferences, aligned with Aoba Club's offerings and character concepts.
    Unspoken_Or_Subtle_Cues_Hinting_At_Preferences: String // AI to infer based on profile, focusing on intriguing hints that add depth.

    // -- Interaction & Temperament (Confident, Enigmatic, or Stylishly Eccentric) --
    Initial_Demeanor_In_Club: RANDOM_SELECTION_PORTRAYING_CONFIDENCE_OR_MYSTIQUE // Portraying confidence, enigma, stylish eccentricity, or purposefulness, avoiding club-specific anxiety.
    Communication_Style: RANDOM_SELECTION_OF_DISTINCTIVE_STYLES // Reflecting distinctive cyberpunk communication patterns: laconic, witty, passionate, cryptic, etc.
    Potential_For_Trouble_Or_Unexpected_Behavior: RANDOM_CHANCE_WEIGHTED_MEDIUM // For narratively interesting, non-mundane 'trouble' or unexpected developments.
    Post_Service_Feedback_Likelihood: RANDOM_SELECTION_OF_MEMORABLE_OUTCOMES // Describing unique, memorable, or impactful post-service outcomes.
}

