// 1. Handlungsfortschritt (推进剧情 - Advance Plot)
//    Ziel: Die aktuelle Szene oder das aktuelle Ereignis auf natürliche Weise zum nächsten logischen Schritt führen.
// -----------------------------------------------------------------------------
FUNCTION QUICK_REPLY_ADVANCE_PLOT()
    // Prüfe den aktuellen Ereignistyp und dessen Phase
    IF (Current_Event_Type == Scheduled_Guest_Session) THEN
        IF (Current_Stage == SERVICE_ENCOUNTER_PART_1) THEN
            // Beschleunige den Abschluss von Teil 1, wenn noch nicht geschehen, und initiiere Teil 2
            // Dies könnte bedeuten, Dialoge zu verkürzen oder Entscheidungen schneller zu treffen.
            // Z.B.: Wenn Gast noch unentschlossen ist, lässt ihn das Mädchen eine schnelle Empfehlung machen.
            CALL COMPLETE_STAGE_AND_TRANSITION(SERVICE_ENCOUNTER_PART_1, SERVICE_ENCOUNTER_PART_2)
            OUTPUT_NARRATION("Die Vorbereitungen sind abgeschlossen, und der eigentliche Service beginnt...")
        ELSE IF (Current_Stage == SERVICE_ENCOUNTER_PART_2) THEN
            // Beschleunige den Service in Richtung Höhepunkt
            // Z.B.: Intensivere Aktionen, direktere Kommunikation zum Höhepunkt.
            CALL ADVANCE_TOWARDS_CLIMAX(Girl_Selected, Guest_Profile, Chosen_Service_Type)
            OUTPUT_NARRATION("Der Service intensiviert sich und nähert sich dem Höhepunkt...")
        ELSE IF (Current_Stage == SERVICE_ENCOUNTER_PART_3) THEN
            // Beschleunige die Verabschiedung und das Aufräumen
            CALL EXPEDITE_DEPARTURE_PROCESS()
            OUTPUT_NARRATION("Nach dem Höhepunkt geht alles schnell; der Gast bereitet sich auf den Abschied vor.")
            CALL QUICK_REPLY_END_CURRENT_EVENT() // Beendet die Gastsitzung nach beschleunigtem Teil 3
        END IF
    ELSE IF (Current_Event_Type == Random_Daily_Activity) THEN
        // Führe eine kleine, kontextrelevante Interaktion oder Beobachtung ein, die die Aktivität vorantreibt
        // oder zu einem interessanten Punkt führt.
        LET Next_Logical_Step = DETERMINE_NEXT_STEP_FOR_ACTIVITY(Current_Daily_Activity, Characters_Involved)
        EXECUTE_ACTIVITY_STEP(Next_Logical_Step)
        OUTPUT_NARRATION("Die tägliche Routine entwickelt sich weiter: " + Next_Logical_Step.Description)
    ELSE IF (Current_Event_Type == Player_Initiated_Action) THEN
        // Führe die Spieleraktion zu einem schnellen Ergebnis oder nächsten Schritt.
        CALL RESOLVE_PLAYER_ACTION_PROMPTLY(Current_Player_Action)
        OUTPUT_NARRATION("Deine Aktion führt schnell zu einem Ergebnis...")
    ELSE
        OUTPUT_NARRATION("Momentan gibt es keine spezifische Handlung, die vorangetrieben werden kann.")
    END IF
    CALL UPDATE_UI_AND_GAME_STATE()
END FUNCTION

// Hilfsfunktion für ADVANCE_PLOT
FUNCTION COMPLETE_STAGE_AND_TRANSITION(CurrentStageFunction, NextStageFunction)
    // Führt die wichtigsten Aktionen von CurrentStageFunction in verkürzter Form aus
    // und initiiert dann NextStageFunction.
    // Z.B. für SERVICE_ENCOUNTER_PART_1:
    //   IF (Guest_Profile.Chosen_Service_Type IS NULL) THEN
    //     Guest_Profile.Chosen_Service_Type = QUICK_RECOMMENDATION(Girl_Selected, Guest_Profile)
    //   END IF
    //   OUTPUT_NARRATION("Der Gast entscheidet sich für " + Guest_Profile.Chosen_Service_Type + ".")
    //   OUTPUT_NARRATION(Girl_Selected.Name + " führt den Gast in " + Girl_Selected.Designated_Room_For_Service + ".")
    // Setze Current_Stage = NextStageFunction
    CALL NextStageFunction(Girl_Selected, Guest_Profile, Guest_Profile.Chosen_Service_Type IF APPLICABLE)
END FUNCTION

