// 4. Zufallsereignis (nicht sexunterbrechend) (随机事件（不打断sex）- Random Event - No Sex Interruption)
//    Ziel: Ein kleines, nicht-störendes Ereignis hinzufügen, das Atmosphäre schafft, besonders während sexueller Handlungen.
// -----------------------------------------------------------------------------
FUNCTION QUICK_REPLY_NON_DISRUPTIVE_RANDOM_EVENT()
    LET Event_Description = ""
    IF (Current_Event_Type == Scheduled_Guest_Session AND Current_Stage == SERVICE_ENCOUNTER_PART_2) THEN
        // Wähle ein Ereignis, das den Service nicht direkt unterbricht
        // Beispiele:
        // - Ein Geräusch von draußen (Sirene, laute Musik aus der Nachbarschaft)
        // - Wallie die Katze miaut vor der Tür oder streicht im Flur vorbei (wenn hörbar)
        // - Ein Licht flackert kurz aufgrund eines Datensturms, aber ohne Geräteausfall
        // - Eine subtile Änderung der Raumtemperatur oder des Dufts
        Event_Description = SELECT_FROM_LIST_OF_MINOR_NON_SEX_INTERRUPTING_EVENTS_DURING_SEX()
    ELSE
        // Allgemeinere kleine Zufallsereignisse
        // Beispiele:
        // - Eine der Mädchen summt eine Melodie
        // - Eine Nachricht ploppt auf Mios Konsole auf (nichts Dringendes)
        // - Der Spieler bemerkt ein Detail im Raum, das ihm vorher nicht aufgefallen ist
        Event_Description = SELECT_FROM_LIST_OF_MINOR_AMBIENT_EVENTS()
    END IF

    IF (Event_Description != "") THEN
        OUTPUT_NARRATION("Zufälliges Ereignis: " + Event_Description)
        // Potenziell kleine Reaktionen der anwesenden Charaktere, wenn angemessen
        FOR EACH Character IN Characters_Present_In_Current_Scene:
            IF (Character_SHOULD_REACT_TO_MINOR_EVENT(Character, Event_Description)) THEN
                OUTPUT_NARRATION(Character.Name + Character_Reacts_Subtly_To_Event(Event_Description))
            END IF
        END FOR
    ELSE
        OUTPUT_NARRATION("Im Moment geschieht nichts Ungewöhnliches.")
    END IF
    CALL UPDATE_UI_AND_GAME_STATE()
END FUNCTION

// -----------------------------------------------------------------------------

