// 5. Aktuelles Ereignis beenden (结束当前事件 - End Current Event)
//    Ziel: Das aktuelle Ereignis oder die aktuelle Aktivität sofort abschließen.
// -----------------------------------------------------------------------------
FUNCTION QUICK_REPLY_END_CURRENT_EVENT()
    IF (Current_Event_Type IS NOT NULL) THEN
        LET Event_Name = Name_Of(Current_Event_Type)
        OUTPUT_NARRATION("Das aktuelle Ereignis (" + Event_Name + ") wird beendet.")

        // Spezifische Abschlusslogik je nach Event-Typ
        IF (Current_Event_Type == Scheduled_Guest_Session) THEN
            // Führe eine stark verkürzte Version von SERVICE_ENCOUNTER_PART_3 aus, falls noch nicht geschehen
            // (z.B. Gast zahlt schnell, verabschiedet sich)
            IF (Current_Stage != SERVICE_ENCOUNTER_PART_3_COMPLETED_FLAG) THEN
                CALL SUMMARIZED_GUEST_DEPARTURE(Girl_Selected, Guest_Profile)
            END IF
            Guest_Profile.Session_Ended_Early = TRUE // Flag für mögliche spätere Auswirkungen
        ELSE IF (Current_Event_Type == Random_Daily_Activity) THEN
            // Markiere die Aktivität als abgeschlossen.
            Current_Daily_Activity.Status = COMPLETED
        ELSE IF (Current_Event_Type == Player_Initiated_Action) THEN
            // Markiere die Spieleraktion als abgeschlossen.
            Current_Player_Action.Status = COMPLETED
        END IF

        CALL POST_EVENT_PROCESSING() // Ruft UPDATE_CHARACTER_STATS, LOG_EVENT etc. auf
        Current_Event_Type = NULL
        Current_Event_Object = NULL
        Current_Stage = NULL
        // Der Haupt-Event-Loop wird nun ein neues Ereignis auswählen.
    ELSE
        OUTPUT_NARRATION("Es läuft derzeit kein aktives Ereignis, das beendet werden könnte.")
    END IF
    CALL UPDATE_UI_AND_GAME_STATE()
END FUNCTION

// -----------------------------------------------------------------------------

