// 6. Kunden generieren (生成顾客 - Generate Customer)
//    Ziel: Einen neuen Kunden für den Aoba Club generieren und eine Servicesitzung initiieren.
// -----------------------------------------------------------------------------
FUNCTION QUICK_REPLY_GENERATE_CUSTOMER()
    IF (IS_SERVICE_SLOT_AVAILABLE() AND ARE_GIRLS_AVAILABLE()) THEN // Prüfe, ob der Club bereit ist
        OUTPUT_NARRATION("Ein neuer potenzieller Kunde nähert sich dem Aoba Club...")
        // Nutze deine verbesserte Kundengenerierungslogik
        New_Guest_Profile = CALL ADVANCED_GUEST_PROFILE_GENERATION_MK_III()

        // Filtere den Gast gemäß den Kriterien (wird von ADVANCED_GUEST_PROFILE_GENERATION_MK_III übernommen)
        // WHILE (Character_Concept_Filter(New_Guest_Profile) == FALSE):
        //    New_Guest_Profile = CALL ADVANCED_GUEST_PROFILE_GENERATION_MK_III()
        // END WHILE
        // Angenommen, ADVANCED_GUEST_PROFILE_GENERATION_MK_III liefert bereits einen validen Gast.

        // Wähle ein Mädchen für den Gast aus (kann Spielerentscheidung oder Automatik sein)
        Assigned_Girl = CALL ASSIGN_GIRL_TO_GUEST(New_Guest_Profile, GET_AVAILABLE_GIRLS_LIST())

        IF (Assigned_Girl IS NOT NULL) THEN
            OUTPUT_NARRATION(New_Guest_Profile.Guest_Alias + " betritt den Club. " + Assigned_Girl.Name + " wird sich um ihn/sie kümmern.")
            // Setze globale Variablen für die neue Sitzung
            Current_Event_Type = Scheduled_Guest_Session
            Girl_Selected = Assigned_Girl
            Guest_Profile = New_Guest_Profile
            Chosen_Service_Type = NULL // Wird in Teil 1 bestimmt
            Current_Stage = SERVICE_ENCOUNTER_PART_1
            // Initiiere die erste Phase der Servicesitzung
            CALL SERVICE_ENCOUNTER_PART_1(Girl_Selected, Guest_Profile)
        ELSE
            OUTPUT_NARRATION("Obwohl ein Gast generiert wurde, ist derzeit kein passendes Mädchen verfügbar.")
            // Gast könnte "weggeschickt" werden oder auf Warteliste landen
        END IF
    ELSE
        OUTPUT_NARRATION("Der Club kann momentan keine neuen Kunden empfangen (z.B. alle Mädchen beschäftigt, Sperrstunde).")
    END IF
    CALL UPDATE_UI_AND_GAME_STATE()
END FUNCTION

